// 事务域各持久字段共用一套冷访问声明，避免JSON与检查点遗漏不同责任。
#pragma once
#include "affairs_model.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
namespace hanmo::resident::affairs_codec {
using namespace dynamic_codec;
// 持续事项保留原发生身份和关闭边界，不能读档时重新制造episode。
template<class A>Status affair(A& a,WorldAffair& v){a.field("id",v.id);a.field("semantic_key",v.semantic_key);a.field("episode",v.episode);a.object("principal",[&](auto& c){return subject(c,v.principal);});strings(a,"cause_fact_ids",v.cause_fact_ids);enumeration(a,"phase",v.phase,5);a.field("opened_tick",v.opened_tick);a.optional("closed_tick",v.closed_tick,[](auto& c,auto& x){return c.field("value",x);});strings(a,"need_ids",v.need_ids);return a.status();}
template<class A>Status need(A& a,Need& v,bool obligation_needs,bool fiscal_needs,bool cohort_wage_needs){a.field("id",v.id);a.field("affair_id",v.affair_id);a.field("source_domain",v.source_domain);a.field("source_key",v.source_key);a.object("beneficiary",[&](auto& c){return subject(c,v.beneficiary);});a.field("target_inventory_id",v.target_inventory_id);a.field("item_id",v.item_id);a.field("unit",v.unit);enumeration(a,"measure",v.measure,(obligation_needs||fiscal_needs||cohort_wage_needs)?2:1);if(v.source_domain=="cohort_wages"&&!cohort_wage_needs)return a.reject("CohortWageNeedsCapabilityRequired");if(v.source_domain=="fiscal_settlement"&&!fiscal_needs)return a.reject("FiscalNeedsCapabilityRequired");if(v.source_domain=="local_economy"&&v.measure==NeedMeasure::outstanding_obligation&&!obligation_needs)return a.reject("ObligationNeedsCapabilityRequired");a.field("revision",v.revision);a.field("created_tick",v.created_tick);a.optional("deadline_tick",v.deadline_tick,[](auto& c,auto& x){return c.field("value",x);});a.field("target_amount",v.target_amount);a.field("fulfilled_amount",v.fulfilled_amount);enumeration(a,"status",v.status,5);strings(a,"receipt_ids",v.receipt_ids);strings(a,"claim_ids",v.claim_ids);a.field("source_fact_id",v.source_fact_id);a.field("policy_id",v.policy_id);a.field("physical_amount",v.physical_amount);a.field("source_revision",v.source_revision);a.field("last_observed_tick",v.last_observed_tick);if(obligation_needs||fiscal_needs||cohort_wage_needs){a.field("obligation_id",v.obligation_id);a.field("arrear_id",v.arrear_id);}else if(!v.obligation_id.empty()||!v.arrear_id.empty())return a.reject("ObligationNeedsCapabilityRequired");return a.status();}
template<class A>Status claim_acceptance(A& a,NeedClaim& v){if(!a.reading()&&!v.accepted_source)return a.reject("NeedClaimAcceptanceSourceMissing",v.id);Integer tag=v.accepted_source?static_cast<Integer>(v.accepted_source->index()):0;a.field("tag",tag);if(tag<0||tag>1)return a.reject("UnknownNeedClaimAcceptanceSource");if(a.reading()){if(tag==0)v.accepted_source=LegacyClaimAcceptedTick{};else v.accepted_source=TaskClaimEstablishedRef{};}if(tag==0){auto& old=std::get<LegacyClaimAcceptedTick>(*v.accepted_source);a.field("accepted_tick",old.accepted_tick);if(a.reading())v.accepted_tick=old.accepted_tick;return a.status();}auto& ref=std::get<TaskClaimEstablishedRef>(*v.accepted_source);a.object("source",[&](auto& x){x.field("domain",ref.source.domain);x.field("kind",ref.source.kind);return x.field("id",ref.source.id);});a.field("source_schema",ref.source_schema);if(ref.source_schema!=1)return a.reject("UnknownTaskClaimSourceSchema");return a.status();}
template<class A>Status claim(A& a,NeedClaim& v,bool exact=false){a.field("id",v.id);a.field("need_id",v.need_id);a.object("assignee",[&](auto& c){return subject(c,v.assignee);});a.field("accepted_amount",v.accepted_amount);a.field("fulfilled_amount",v.fulfilled_amount);if(exact)a.object("accepted_source",[&](auto& x){return claim_acceptance(x,v);});else a.field("accepted_tick",v.accepted_tick);a.field("expires_tick",v.expires_tick);enumeration(a,"status",v.status,4);a.field("contract_id",v.contract_id);return a.status();}
template<class A>Status contribution(A& a,ContributionUse& v){a.field("receipt_id",v.receipt_id);a.field("transfer_fact_id",v.transfer_fact_id);a.field("contract_id",v.contract_id);a.field("claim_id",v.claim_id);a.field("need_id",v.need_id);a.field("counted_amount",v.counted_amount);return a.status();}
template<class A>Status state(A& a,AffairsState& v){if(v.cohort_wage_needs){Integer version=1;a.field("cohort_wage_need_policies_version",version);if(version!=1)return a.reject("UnsupportedCohortWageNeedVersion");}if(v.fiscal_needs){Integer version=1;a.field("fiscal_need_policies_version",version);if(version!=1)return a.reject("UnsupportedFiscalNeedVersion");}if(v.obligation_needs){Integer version=1;a.field("obligation_needs_version",version);if(version!=1)return a.reject("UnsupportedObligationNeedsVersion");}table(a,"affairs",v.affairs,[](auto& c,auto& x){return affair(c,x);});table(a,"needs",v.needs,[&](auto& c,auto& x){return need(c,x,v.obligation_needs,v.fiscal_needs,v.cohort_wage_needs);});table(a,"claims",v.claims,[&](auto& c,auto& x){return claim(c,x,v.exact_claims);});table(a,"contributions",v.contributions,[](auto& c,auto& x){return contribution(c,x);});return a.status();}
} // 校验器在全域构造后再检查来源、合同、实物和一次性计入关系。
